WITH cap AS (SELECT DISTINCT order_id FROM payments WHERE status = 'captured'), ref AS (SELECT DISTINCT order_id FROM refunds) SELECT r.name, AVG(CASE WHEN ref.order_id IS NOT NULL THEN 1.0 ELSE 0.0 END) AS refund_rate FROM orders o JOIN cap ON cap.order_id = o.order_id JOIN customer_addresses a ON a.address_id = o.address_id JOIN cities ci ON ci.city_id = a.city_id JOIN regions r ON r.region_id = ci.region_id LEFT JOIN ref ON ref.order_id = o.order_id WHERE NOT o.is_deleted AND CAST(o.order_at AS DATE) BETWEEN DATE '2025-02-01' AND DATE '2025-02-28' GROUP BY r.name ORDER BY refund_rate DESC LIMIT 1
